     * @covers ::__construct
     * @covers ::getTheme
     * @covers ::setTheme
     * @covers ::offsetExists
     * @covers ::offsetGet
     * @covers ::offsetSet
     * @covers ::offsetUnset
     */
    public function testPropertyTheme(): void
    {
        // @todo can we assert anything useful about the default?
        $v = $this->getFakeValue(
            $this->types['theme'],
            $this->allowedValues['theme'] ?? null
        );
        $this->sot->setTheme($v);
        $this->assertEquals($v, $this->sot->getTheme());
        $this->sot->setTheme(null);
        $this->assertNull($this->sot->getTheme());
        $this->sot->setTheme($v);

        $this->assertEquals($v, $this->sot['theme']);
        $v = $this->getFakeValue(
            $this->types['theme'],
            $this->allowedValues['theme'] ?? null
        );
        $this->sot['theme'] = $v;
        $this->assertTrue(isset($this->sot['theme']));
        $this->assertEquals($v, $this->sot['theme']);
        $this->assertEquals($v, $this->sot->getTheme());
        unset($this->sot['theme']);
        $this->assertFalse(isset($this->sot['theme']));
        $this->sot['theme'] = $v;
        $this->assertEquals($v, $this->sot['theme']);
        $this->assertTrue(isset($this->sot['theme']));
        $this->sot['theme'] = null;
        $this->assertFalse(isset($this->sot['theme']));
    }

    /**
     * Test invalid use of offsetSet.
     *
     * @covers ::offsetSet
     */
    public function testInvalidOffsetException(): void
    {
        $this->expectException(\RuntimeException::class);
        $this->sot[] = 'foobar';
    }
}
